import { activityView, newJobForm } from './activity-view.js';
import { icon } from './icons.js';
import { currentDictation, currentBlocks, pendingChanges, compileContext, escapeHtml as e, time, wordCount, STRATEGIES, MODEL_OPTIONS } from './store.js';
import { IMPORT_EXAMPLE, SIMULATION, AUDIO_INPUT_OPTIONS, WORKSPACE_AVATAR } from '../fixtures/demo-data.js';

const btn = (action, label, glyph, classes = '', attrs = '') => `<button type="button" class="button ${classes}" data-action="${action}" ${attrs}>${glyph ? icon(glyph) : ''}<span>${label}</span></button>`;
const ib = (action, label, glyph, classes = '', attrs = '') => `<button type="button" class="icon-button ${classes}" data-action="${action}" aria-label="${label}" title="${label}" ${attrs}>${icon(glyph)}</button>`;
const badge = (label, color = '') => `<span class="badge ${color}">${e(label)}</span>`;
const detail = (label, value) => `<div class="detail-row"><span>${label}</span><strong>${e(value)}</strong></div>`;
const code = object => `<pre class="code-block">${e(typeof object === 'string' ? object : JSON.stringify(object, null, 2))}</pre>`;
const empty = (glyph, title, description) => `<div class="empty-state">${icon(glyph)}<h3>${title}</h3><p>${description}</p></div>`;
const section = (title, body, extra = '') => `<section class="inspector-section"><div class="section-heading"><h3>${title}</h3>${extra}</div>${body}</section>`;

export function header(s) {
  return `<header class="app-header"><div class="brand">${ib('toggle-sidebar', 'Open dictation library', 'layers', 'mobile-menu')}<span class="brand-mark">${icon('wave')}</span><span>Speech Dictation<small>STUDIO</small></span></div><nav class="top-nav" aria-label="Workspace"><button data-action="page" data-value="studio" class="${s.page === 'studio' ? 'active' : ''}">Workspace</button><button data-action="page" data-value="jobs" class="${s.page === 'jobs' ? 'active' : ''}">Activity<span class="count-dot">${s.jobs.filter(j => j.state === 'Running').length}</span></button></nav><div class="header-actions"><span class="demo-badge"><span></span>Interactive mock-up</span>${ib('shortcuts', 'Keyboard shortcuts', 'keyboard', 'desktop-only')}${ib('settings', 'Settings', 'settings')}<span class="avatar" title="Local preview workspace">${e(WORKSPACE_AVATAR)}</span></div></header>`;
}

export function sidebar(s) {
  const query = s.libraryQuery.toLowerCase();
  const rows = s.dictations.filter(r => (r.title + ' ' + r.tags.join(' ')).toLowerCase().includes(query));
  let lastGroup = '';
  return `<aside class="sidebar ${s.sidebarOpen ? 'mobile-open' : ''}" aria-label="Dictations"><div class="sidebar-top">${btn('new-recording', 'New dictation', 'plus', 'primary full')}<div class="library-search">${icon('search')}<input id="library-search" aria-label="Search dictations" placeholder="Search dictations…" value="${e(s.libraryQuery)}"/><kbd>/</kbd></div></div><div class="library-label"><span>DICTATIONS</span><span>${s.dictations.length}</span></div><div class="recording-list">${rows.map(r => { const group = r.group !== lastGroup ? `<div class="date-group">${e(r.group)}</div>` : ''; lastGroup = r.group; return `${group}<button class="recording-item ${s.dictationId === r.id ? 'selected' : ''}" data-action="select-source" data-id="${r.id}"><span class="recording-icon">${icon(r.type === 'Microphone' ? 'wave' : 'file')}</span><span class="recording-info"><strong>${e(r.title)}</strong><span>${time(r.duration)}<i>·</i>${e(r.tags[0] || 'New take')}</span><small class="${r.status.includes('review') ? 'amber-text' : ''}">${r.status.includes('review') ? '<span class="tiny-dot amber"></span>' : ''}${e(r.status)}</small></span></button>`; }).join('') || '<p class="muted padded">No matching dictations.</p>'}</div><div class="sidebar-footer">${btn('import', 'Import audio', 'upload', 'full subtle')}<div class="storage-caption">${icon('layers')}<span>Sample workspace<small>All content is illustrative</small></span>${ib('reset-demo', 'Reset sample workspace', 'undo')}</div></div></aside>`;
}

function markedText(s, block) {
  let text = e(block.text);
  if (s.findQuery) { const query = e(s.findQuery); const index = text.toLowerCase().indexOf(query.toLowerCase()); if (index >= 0) text = text.slice(0, index) + '<mark class="search-match">' + text.slice(index, index + query.length) + '</mark>' + text.slice(index + query.length); }
  else if (s.settings.showAnnotations && s.documentMode === 'working') {
    const change = s.changes.find(c => c.blockId === block.id && c.state === 'pending');
    if (change) text = text.replace(e(change.before), `<mark class="suggestion ${change.type === 'Meaning' ? 'meaning' : ''}" title="${e(change.title)}">${e(change.before)}</mark>`);
    else if (block.revised) text = `<span class="revised-text">${text}</span>`;
  }
  return text;
}

export function documentView(s) {
  const r = currentDictation(s); const blocks = s.documentMode === 'source' ? r.blocks : currentBlocks(s); const pending = pendingChanges(s);
  return `<main id="document" class="workspace" tabindex="-1"><div class="document-toolbar"><div class="segmented" role="group" aria-label="Document view"><button class="${s.documentMode === 'working' ? 'active' : ''}" data-action="document-mode" data-value="working">Working document</button><button class="${s.documentMode === 'source' ? 'active' : ''}" data-action="document-mode" data-value="source">Source transcript</button></div><div class="toolbar-actions">${ib('undo', 'Undo last edit', 'undo', '', s.undoStack.length ? '' : 'disabled')}${ib('find', 'Find in document', 'search', s.findOpen ? 'active' : '')}${ib('focus', 'Toggle focus mode', 'layers', s.focusMode ? 'active' : '')}${btn('toggle-inspector', s.inspectorOpen ? 'Inspector' : 'Inspect', 'panel', s.inspectorOpen ? 'selected-button' : '')}</div></div>${s.findOpen ? `<div class="find-bar">${icon('search')}<input id="document-find" placeholder="Find in this document…" aria-label="Find in document" value="${e(s.findQuery)}"/>${ib('find', 'Close find', 'close')}</div>` : ''}<div class="document-scroll"><article class="paper"><div class="document-eyebrow"><span class="tiny-dot ${s.recording ? 'red' : 'green'}"></span>${s.recording ? 'SIMULATED RECORDING' : e(r.date)}<span class="eyebrow-divider">/</span>${time(r.duration)}<span class="eyebrow-divider">/</span>${e(r.language)}</div><h1>${e(r.title)}</h1><div class="document-tags">${r.tags.map(t => `<button class="tag" data-action="tag" data-value="${e(t)}">${e(t)}</button>`).join('')}${btn('add-tag', 'Add tag', 'plus', 'text-button')}</div><div class="document-status"><span>${icon(s.recording ? 'mic' : 'check')}<span id="save-status">${s.recording ? 'Preview capture · no microphone access' : 'Sample document · editable in this session'}</span></span>${pending.length ? `<button class="review-button" data-action="review">${icon('sparkles')}${pending.length} suggestions</button>` : `<span class="green-text">${icon('check')}No pending proposals</span>`}</div>${s.documentMode === 'source' ? '<div class="source-notice">Original ASR text · preserved as recognition evidence</div>' : ''}<div class="text-blocks">${blocks.map(b => `<section class="text-block ${s.selectedBlockId === b.id ? 'selected-block' : ''} ${s.editedBlocks.has(b.id) ? 'human-edited' : ''}" data-block="${b.id}"><button class="timestamp" data-action="select-block" data-id="${b.id}" aria-label="Inspect passage at ${time(b.start)}">${time(b.start)}</button><div class="block-content">${b.label ? `<div class="block-label">${e(b.label)}</div>` : ''}${b.speaker ? `<div class="speaker-label"><span></span>${e(b.speaker)}</div>` : ''}<p ${s.documentMode === 'working' ? 'contenteditable="plaintext-only" role="textbox" aria-multiline="true" spellcheck="false"' : ''} aria-label="Passage at ${time(b.start)}" data-edit-block="${b.id}">${markedText(s, b)}</p>${s.editedBlocks.has(b.id) ? '<div class="edit-footnote">Your edit · protected</div>' : ''}</div><button class="block-inspect" data-action="select-block" data-id="${b.id}" aria-label="Inspect this passage">${icon('more')}</button></section>`).join('')}${s.recording ? `<section class="live-tail"><span class="live-dot"></span><div><span id="live-partial">${s.recordingPaused ? 'Capture paused' : 'Waiting for simulated speech…'}</span><small>Simulated preview · growing window</small></div></section>` : ''}${!blocks.length && !s.recording ? empty('mic', 'Empty dictation', 'Start the recording preview or import an example to explore the workspace.') : ''}</div><div class="document-end"><span></span>${icon('wave')}<span></span></div><div class="paper-footer"><span id="word-count">${wordCount(blocks)} words</span><span>Version ${s.version}</span><span>${s.documentMode === 'working' ? 'Click any paragraph to edit' : 'Read-only evidence'}</span></div></article></div><div class="workspace-bottom"><button data-action="settings" data-settings-tab="models">${icon('sparkles')}${e(s.settings.profile)}${icon('down')}</button><span>${s.editedBlocks.size ? `${s.editedBlocks.size} protected edit${s.editedBlocks.size > 1 ? 's' : ''}` : 'Manual edits protected'}</span>${btn('dictation-jobs', 'Jobs', 'activity', 'text-button')}${btn('export', 'Export', 'download', 'text-button')}</div></main>`;
}

function changesPanel(s) {
  const all = s.changes.filter(c => c.dictationId === s.dictationId); const filtered = all.filter(c => s.changeFilter === 'all' || c.state === s.changeFilter);
  return `<div class="panel-intro"><div class="overline">REVISION QUEUE</div><h2>Revision proposals</h2><p>Inspect proposed edits and supporting recognition results.</p></div><div class="panel-filter"><div class="segmented small"><button data-action="change-filter" data-value="pending" class="${s.changeFilter === 'pending' ? 'active' : ''}">To review ${all.filter(c => c.state === 'pending').length}</button><button data-action="change-filter" data-value="all" class="${s.changeFilter === 'all' ? 'active' : ''}">All changes</button></div></div>${filtered.map(c => `<article class="change-card ${s.selectedBlockId === c.blockId ? 'selected' : ''}"><div class="change-heading">${badge(c.type, c.type === 'Meaning' ? 'amber' : 'teal')}<button class="text-link mono" data-action="select-block" data-id="${c.blockId}">${time(c.time[0])}–${time(c.time[1])}</button></div><h3>${e(c.title)}</h3><div class="diff-line"><del>${e(c.before)}</del>${icon('arrow')}<ins>${e(c.after)}</ins></div><p>${e(c.explanation)}</p><button class="evidence-link" data-action="evidence" data-id="${c.evidence[c.evidence.length - 1]}">${icon('layers')}${c.evidence.length} recognition result${c.evidence.length > 1 ? 's' : ''}${icon('chevron')}</button><div class="change-actions">${c.state === 'pending' ? `${btn('accept-change', 'Accept', 'check', 'primary small-button', `data-id="${c.id}"`)}${btn('dismiss-change', 'Keep original', '', 'small-button', `data-id="${c.id}"`)}` : badge(c.state === 'accepted' ? 'Accepted' : 'Original kept', c.state === 'accepted' ? 'green' : '')}</div><div class="change-provenance">${icon('sparkles')}${e(c.model)}<span>· ${c.baseVersion}</span></div></article>`).join('') || empty('check', 'No pending proposals', 'New proposals will appear here. Manual edits are protected.')}<div class="inspector-footnote">${icon('lock')}Changes are checked against the version they were based on.</div>`;
}

function recognitionPanel(s) {
  const list = s.requests.filter(r => r.dictationId === s.dictationId); const r = list.find(r => r.id === s.requestId) || list[0];
  if (!r) return `<div class="panel-intro"><div class="overline">RECOGNITION</div><h2>Recognition requests</h2></div>${empty('wave', 'No requests yet', 'Recognition requests will appear here as audio windows are submitted.')} ${btn('simulate-request', 'Simulate a request', 'plus', 'full')}`;
  return `<div class="panel-intro compact"><div class="overline">AUDIO & ASR</div><h2>Recognition requests</h2><p>Inspect submitted audio, frozen context, and execution results.</p></div><div class="request-picker"><label for="request-select">Recognition request</label><select id="request-select">${list.map(q => `<option value="${q.id}" ${q.id === r.id ? 'selected' : ''}>${q.id} · ${q.purpose}</option>`).join('')}</select></div><div class="request-summary"><span class="model-symbol">${icon('wave')}</span><div><strong>${e(r.model)}</strong><small>${e(r.purpose)}</small></div>${badge(r.status, r.status === 'Complete' ? 'green' : r.status === 'Failed' ? 'red' : 'blue')}</div>${r.attemptId ? `<div class="request-activity-link">${btn('activity-reference', 'Job / span / attempt', 'activity', 'text-button', `data-id="${r.attemptId}"`)}</div>` : ''}<div class="sub-tabs" role="group" aria-label="Request details">${['details', 'context', 'response'].map(t => `<button data-action="request-tab" data-value="${t}" class="${s.requestTab === t ? 'active' : ''}">${t[0].toUpperCase() + t.slice(1)}</button>`).join('')}</div>${s.requestTab === 'details' ? `${section('Audio submitted', `<div class="range-card"><div><span>INPUT WINDOW</span><strong>${time(r.input[0])} – ${time(r.input[1])}</strong></div>${ib('play-request', 'Preview this audio range', 'play', '', `data-id="${r.id}"`)}</div>${detail('Target interval', `${time(r.target[0])} – ${time(r.target[1])}`)}${detail('Format', r.format)}${detail('Payload', r.bytes)}${detail('Mapping', 'Input range · no word timing')}`)}${section('Request lifecycle', `<ol class="event-list">${r.events.map(ev => `<li><span class="event-dot"></span><span>${e(ev.event)}</span><time>${e(ev.time)}</time></li>`).join('')}</ol>`)}${section('Parameters', `<details class="json-disclosure"><summary>Exact request parameters${icon('down')}</summary>${code(r.params)}</details>`)}<div class="panel-action-row">${btn('rerun', 'Run again', 'loop', '', `data-id="${r.id}"`)}${btn('request-context', 'Primer v' + r.contextVersion, 'compass', 'subtle', `data-id="${r.id}"`)}</div>` : s.requestTab === 'context' ? `${section('Frozen at dispatch', `<p class="panel-copy">This is the context this request saw. Later primer updates do not change it.</p>${detail('Primer snapshot', `v${r.contextVersion}`)}${detail('Dispatched', r.created)}`)}${section('Prompt', `<div class="context-quote">${e(r.prompt)}</div>`)}${section('Keywords', `<div class="term-chips">${r.keywords.map(k => `<span>${e(k)}</span>`).join('') || '<span class="muted">Included in prompt for this model</span>'}</div>`)}` : `${section(r.status === 'Complete' ? 'Recognition result' : 'Execution status', `<div class="response-text">${e(r.text)}</div>`)}${section('Provenance', `${detail('Request', r.id)}${detail('Model', r.model)}${detail('Input', `${time(r.input[0])}–${time(r.input[1])}`)}${detail('Result', 'Immutable evidence')}`)}<div class="quiet-note">${icon('info')}Results remain independent across attempts. Document application is tracked separately.</div>`}`;
}

function contextPanel(s) {
  const p = s.primer;
  if (s.contextRequestId) { const r = s.requests.find(r => r.id === s.contextRequestId); return `<div class="panel-intro"><div class="overline">FROZEN SNAPSHOT · V${r.contextVersion}</div><h2>Context at dispatch.</h2><p>${e(r.id)} · ${e(r.model)}</p></div>${section('Prompt', `<div class="context-quote">${e(r.prompt)}</div>`)}${section('Keywords', `<div class="term-chips">${r.keywords.map(k => `<span>${e(k)}</span>`).join('') || '<span class="muted">None</span>'}</div>`)}${btn('current-context', 'Back to active primer', 'arrow', 'full')}`; }
  return `<div class="panel-intro"><div class="overline">SHARED PRIMER · V${p.version}</div><h2>Topic primer</h2><p>Versioned context shared by ASR and text correction.</p></div><div class="sub-tabs" role="group" aria-label="Context view">${[['primer', 'Primer'], ['asr', 'ASR input'], ['corrector', 'Corrector']].map(([t, l]) => `<button data-action="context-tab" data-value="${t}" class="${s.contextTab === t ? 'active' : ''}">${l}</button>`).join('')}</div>${s.contextTab === 'primer' ? `${section('Current topic', `<textarea id="topic-editor" class="topic-editor" aria-label="Current topic">${e(p.topic)}</textarea><div class="context-meta"><span>${icon('compass')}${e(p.scope)}</span>${btn('save-topic', 'Save', '', 'small-button')}</div>`)}${section('Active vocabulary', `<div class="vocabulary-list">${p.terms.filter(t => t.state === 'active').map(t => `<div class="vocabulary-row"><span class="term-icon">${icon('check')}</span><div><strong>${e(t.text)}</strong><small>${e(t.origin)}</small></div>${ib('remove-term', `Remove ${e(t.text)} from active vocabulary`, 'close', '', `data-id="${t.id}"`)}</div>`).join('')}</div>${btn('add-term', 'Add a term', 'plus', 'text-button')}`, badge(p.terms.filter(t => t.state === 'active').length))}${p.terms.some(t => t.state === 'proposed') ? section('Suggested terminology', p.terms.filter(t => t.state === 'proposed').map(t => `<div class="proposed-term"><strong>${e(t.text)}</strong><p>Proposed by the primer model. Not sent as a keyword yet.</p><div>${btn('approve-term', 'Confirm term', 'check', 'small-button', `data-id="${t.id}"`)}${btn('remove-term', 'Dismiss', '', 'text-button small-button', `data-id="${t.id}"`)}</div></div>`).join('')) : ''}${section('Recent speech', `<div class="context-quote small-quote">${e(p.recentSpeech)}</div><p class="micro-copy">From the recognition transcript, before editorial rewrites.</p>`)}<div class="inspector-footnote">${icon('lock')}Ordinary document edits don’t silently become recognition facts.</div>` : `<div class="preview-caption"><span class="tiny-dot green"></span>Next request preview · v${p.version}</div>${code(compileContext(s, s.contextTab))}<div class="quiet-note">${icon('info')}${s.contextTab === 'asr' ? 'Literal terms become keywords where supported. Topic and recent speech become the prompt.' : 'The corrector also receives terminology provenance and the permitted editing policy.'}</div>`}`;
}

function modelsPanel(s) {
  return `<div class="panel-intro"><div class="overline">PIPELINE CONFIGURATION</div><h2>Model configuration</h2><p>Models, input capabilities, and stage configuration.</p></div>${s.models.map((m, index) => { const name = index === 0 ? s.settings.asrModel : index === 1 ? s.settings.correctorModel : s.settings.primerModel; return `<section class="model-card"><div class="model-card-top"><span class="model-symbol ${index === 1 ? 'purple' : ''}">${icon(m.icon)}</span><span class="overline">${e(m.role)}</span><span class="step-number">0${index + 1}</span></div><h3>${e(name)}</h3><p>${e(index === 0 && s.settings.strategy === 'native' ? 'Persistent transcription session' : m.purpose)}</p><div class="model-note">${e(index === 0 ? STRATEGIES[s.settings.strategy] : m.note)}</div><details><summary>Capabilities & configuration${icon('down')}</summary>${Object.entries(m.details).map(([k, v]) => detail(k[0].toUpperCase() + k.slice(1), index === 0 && k === 'endpoint' && s.settings.strategy === 'native' ? 'Realtime transcription session' : index === 0 && k === 'context' && name === 'gpt-4o-transcribe' ? 'Prompt, language; terms included in prompt' : v)).join('')}</details></section>`; }).join('')}<div class="inspector-section">${btn('settings', 'Configure models', 'settings', 'full', 'data-settings-tab="models"')}</div><div class="quiet-note">${icon('info')}Illustrative configuration only. No model is connected and no API calls are made.</div>`;
}

export function inspector(s) {
  const tabs = [['recognition', 'Recognition', 'wave'], ['changes', 'Changes', 'sparkles'], ['context', 'Context', 'compass'], ['models', 'Models', 'layers']];
  return `<aside class="inspector ${s.inspectorOpen ? 'is-open' : ''}" aria-label="Inspector"><div class="inspector-header"><span>${icon('panel')}Inspector</span>${ib('toggle-inspector', 'Close inspector', 'close')}</div><div class="inspector-tabs" role="group" aria-label="Inspector panels">${tabs.map(([id, label, glyph]) => `<button data-action="inspector" data-value="${id}" class="${s.inspector === id ? 'active' : ''}" aria-pressed="${s.inspector === id}">${icon(glyph)}<span>${label}</span>${id === 'changes' && pendingChanges(s).length ? '<i class="tab-dot"></i>' : ''}</button>`).join('')}</div><div class="inspector-scroll">${s.inspector === 'changes' ? changesPanel(s) : s.inspector === 'recognition' ? recognitionPanel(s) : s.inspector === 'context' ? contextPanel(s) : modelsPanel(s)}</div></aside>`;
}

export function transport(s) {
  const r = currentDictation(s); const duration = Math.max(r.duration, 1); const pct = Math.min(100, s.position / duration * 100);
  const reqs = s.requests.filter(q => q.dictationId === s.dictationId);
  return `<footer class="transport ${s.recording ? 'recording' : ''}" aria-label="Audio controls"><div class="transport-heading"><div><span class="tiny-dot ${s.recording ? 'red' : 'green'}"></span><strong>${s.recording ? s.recordingPaused ? 'Recording paused' : 'Recording preview' : 'Audio timeline'}</strong><span class="transport-caption">${s.recording ? 'Simulated capture' : 'Visual playback preview'}</span></div><div class="transport-view-actions">${btn('marker', 'Marker', 'bookmark', 'text-button')}${btn('settings', 'Input', 'sliders', 'text-button', 'data-settings-tab="audio"')}</div></div><div class="timeline-wrap"><div class="timeline-labels"><span>00:00</span><span>${time(duration * .25)}</span><span>${time(duration * .5)}</span><span>${time(duration * .75)}</span><span>${time(duration)}</span></div><div class="waveform-track" id="waveform" style="--played:${pct}%" role="slider" tabindex="0" aria-label="Audio position" aria-valuemin="0" aria-valuemax="${Math.floor(duration)}" aria-valuenow="${Math.floor(s.position)}" aria-valuetext="${time(s.position)} of ${time(duration)}"><div class="wave-bars">${r.waveform.map((h, i, arr) => `<i class="${i / arr.length * 100 < pct ? 'heard' : ''}" style="height:${h}px"></i>`).join('')}</div><div class="playhead"><span></span></div>${r.markers.map(m => `<button class="timeline-marker" data-action="seek" data-time="${m.time}" style="left:${m.time / duration * 100}%" title="${e(m.label)}" aria-label="${e(m.label)} at ${time(m.time)}">${icon('bookmark')}</button>`).join('')}</div><div class="coverage-lane" aria-label="Recognition coverage">${reqs.length ? reqs.map((q, i) => `<button data-action="evidence" data-id="${q.id}" class="coverage-segment coverage-${q.status.toLowerCase()} ${q.id === s.requestId ? 'active' : ''} ${i % 2 ? 'secondary' : ''}" style="left:${q.input[0] / duration * 100}%;width:${Math.max(1, (q.input[1] - q.input[0]) / duration * 100)}%" title="${q.id}: ${time(q.input[0])}–${time(q.input[1])}" aria-label="Inspect ${q.id}"></button>`).join('') : '<span class="coverage-empty"></span>'}</div></div><div class="transport-controls"><div class="playback-buttons">${ib('record', s.recording ? 'Stop simulated recording' : 'Start recording preview', s.recording ? 'stop' : 'mic', 'record-button ' + (s.recording ? 'live' : ''))}<span class="control-divider"></span>${ib('skip-back', 'Back 5 seconds', 'back')}${ib('play', s.recording ? s.recordingPaused ? 'Resume recording preview' : 'Pause recording preview' : s.playing ? 'Pause playback preview' : 'Play preview', s.recording ? s.recordingPaused ? 'play' : 'pause' : s.playing ? 'pause' : 'play', 'play-button')}${ib('skip-forward', 'Forward 5 seconds', 'forward')}<span class="time-display"><strong id="time-current">${time(s.recording ? s.captureSeconds : s.position)}</strong><span>/ ${time(duration)}</span></span></div><button class="pipeline-pill" data-action="inspector" data-value="models"><span class="tiny-dot green"></span>${e(s.settings.asrModel)}<span class="pill-divider">/</span>${e(STRATEGIES[s.settings.strategy])}${icon('chevron')}</button><div class="playback-options"><button class="speed-button" data-action="speed" title="Change preview playback speed">${s.speed}×</button>${ib('loop', 'Loop selected passage', 'loop', s.loop ? 'active' : '')}${ib('volume', 'Audio preview information', 'volume')}</div></div></footer>`;
}

const field = (label, control, help = '') => `<label class="setting-field"><span>${label}</span>${control}${help ? `<small>${help}</small>` : ''}</label>`;
const select = (key, values, selected) => `<select data-setting="${key}">${values.map(v => { const [value, label] = Array.isArray(v) ? v : [v, v]; return `<option value="${e(value)}" ${selected === value ? 'selected' : ''}>${e(label)}</option>`; }).join('')}</select>`;
const toggle = (key, label, description, value) => `<label class="toggle-row"><span><strong>${label}</strong><small>${description}</small></span><input type="checkbox" role="switch" data-setting="${key}" ${value ? 'checked' : ''}/><span class="toggle-track"></span></label>`;

function settingsModal(s) {
  const p = s.settings;
  const menu = [['models', 'Models & processing', 'layers'], ['audio', 'Audio & capture', 'mic'], ['editor', 'Editor & review', 'edit'], ['appearance', 'Appearance', 'sun']];
  let body = '';
  if (s.settingsTab === 'models') body = `<h3>Models & processing</h3><p class="modal-description">Choose each stage independently. Changes apply to future simulated requests.</p><div class="settings-section-label">RECOGNITION</div>${field('ASR model', select('asrModel', MODEL_OPTIONS, p.asrModel))}${field('Processing strategy', select('strategy', Object.entries(STRATEGIES).filter(([k]) => p.asrModel === 'gpt-live-transcribe' ? k === 'native' : k !== 'native'), p.strategy), 'One span and partitioned audio use the same bounded-request executor.')}${p.strategy === 'growing' ? `<div class="setting-grid">${field('First window', `<div class="unit-input"><input type="number" min="2" max="30" data-setting="targetSeconds" value="${p.targetSeconds}"/><span>seconds</span></div>`)}${field('Expanded window', `<div class="unit-input"><input type="number" min="5" max="120" data-setting="windowSeconds" value="${p.windowSeconds}"/><span>seconds</span></div>`)}</div>` : ''}${field('Context policy', select('contextPolicy', ['Latest available', 'Prefer preceding result', 'Require preceding result', 'Fixed snapshot'], p.contextPolicy))}<div class="settings-section-label">TEXT & CONTEXT</div>${field('Recognition corrector', select('correctorModel', ['gpt-4.1-mini', 'gpt-4.1'], p.correctorModel))}${field('Topic primer model', select('primerModel', ['gpt-4.1-mini', 'gpt-4.1'], p.primerModel))}${field('Text-processing profile', select('profile', ['Verbatim', 'Light cleanup', 'Structured notes'], p.profile))}<div class="quiet-note">${icon('info')}Model choices are illustrative. No credentials or API connection are required for this mock-up.</div>`;
  else if (s.settingsTab === 'audio') body = `<h3>Audio & capture</h3><p class="modal-description">Explore the intended capture controls. This preview never opens your microphone.</p>${field('Input device', select('device', AUDIO_INPUT_OPTIONS, p.device))}<div class="input-preview"><span>INPUT LEVEL · ILLUSTRATIVE</span><div class="level-meter">${Array.from({ length: 26 }, (_, i) => `<i class="${i < 18 ? 'on' : ''}"></i>`).join('')}</div><small>${SIMULATION.audioDeviceLevel} dB · healthy input</small></div>${toggle('noiseSuppression', 'Noise suppression', 'Reduce steady background noise.', p.noiseSuppression)}${toggle('echoCancellation', 'Echo cancellation', 'Reduce audio returning from your speakers.', p.echoCancellation)}${section('Recording format', detail('Capture', '48 kHz · mono') + detail('Storage', 'Independent audio blocks') + detail('ASR preparation', 'Per-request format and sample rate'))}`;
  else if (s.settingsTab === 'editor') body = `<h3>Editor & review</h3><p class="modal-description">Configure revision behavior and annotations.</p>${toggle('autoApply', 'Apply supported corrections automatically', 'Preview preference only. Manual edits remain protected.', p.autoApply)}${toggle('showAnnotations', 'Show revision annotations', 'Underline passages with a pending suggestion.', p.showAnnotations)}${toggle('followPlayback', 'Follow playback', 'Select the passage under the preview playhead.', p.followPlayback)}${field('Text size', select('fontSize', [['comfortable', 'Comfortable'], ['large', 'Large']], p.fontSize))}<div class="quiet-note">${icon('lock')}Recognition evidence remains available after every edit. Accepting a proposal is undoable.</div>`;
  else body = `<h3>Appearance</h3><p class="modal-description">Set workspace appearance.</p><div class="theme-options">${['light', 'dark'].map(t => `<button data-action="theme" data-value="${t}" class="theme-card ${t} ${p.theme === t ? 'selected' : ''}"><span class="theme-preview"><i></i><i></i><i></i></span><strong>${icon(t === 'light' ? 'sun' : 'moon')}${t === 'light' ? 'Light' : 'Dark'}${p.theme === t ? icon('check') : ''}</strong></button>`).join('')}</div><p class="micro-copy">Your theme applies throughout the workspace, editor, and inspector.</p>`;
  return `<div class="settings-layout"><nav class="settings-nav" aria-label="Settings sections">${menu.map(([id, label, glyph]) => `<button data-action="settings-tab" data-value="${id}" class="${s.settingsTab === id ? 'active' : ''}">${icon(glyph)}${label}</button>`).join('')}<div class="settings-nav-note">Speech Dictation<small>Alpha interface preview</small></div></nav><div class="settings-content">${body}</div></div>`;
}

export function modal(s) {
  if (!s.modal) return '';
  let title = '', body = '', footer = '', wide = false;
  if (s.modal === 'new-job') { title = 'New recognition job'; body = newJobForm(s); footer = `${btn('close-modal', 'Cancel', '', '')}${btn('create-job', 'Create job', 'plus', 'primary')}`; }
  else if (s.modal === 'settings') { title = 'Workspace settings'; body = settingsModal(s); wide = true; footer = `<span>Preferences affect this mock-up only</span>${btn('close-modal', 'Done', 'check', 'primary')}`; }
  else if (s.modal === 'export') { title = 'Export document'; body = `<p class="modal-description">Export the current text, including your edits in this preview.</p>${field('Content', '<select id="export-content"><option value="working">Working document</option><option value="source">Recognition transcript</option><option value="evidence">Recognition evidence</option></select>')}${field('Format', '<select id="export-format"><option value="txt">Plain text (.txt)</option><option value="md">Markdown (.md)</option><option value="json">JSON (.json)</option></select>')}<div class="export-preview">${icon('file')}<div><strong>${e(currentDictation(s).title)}</strong><small>${wordCount(currentBlocks(s))} words · includes sample content</small></div></div>`; footer = `${btn('close-modal', 'Cancel', '', '')}${btn('download', 'Download', 'download', 'primary')}`; }
  else if (s.modal === 'import') { title = 'Import audio'; body = `<p class="modal-description">Preview a long recording processed as a background job.</p><label class="upload-zone" for="audio-file">${icon('upload')}<strong>Choose an audio file</strong><span>or use the example below · nothing is uploaded</span><input id="audio-file" type="file" accept="audio/*"/></label><div class="import-file">${icon('file')}<div><strong id="import-name">${e(IMPORT_EXAMPLE.name)}</strong><small id="import-meta">${IMPORT_EXAMPLE.size} · 2 hours · example audio</small></div>${badge('Sample')}</div><div class="setting-grid">${field('Plan', '<select id="import-plan"><option value="partitioned">Partitioned audio</option><option value="single">One audio span</option></select>')}${field('Parts', `<input id="import-parts" type="number" min="1" max="100" value="${IMPORT_EXAMPLE.parts}"/>`)}</div>${field('Deliver results to', '<select id="import-destination"><option value="background">Background evidence only</option><option value="document">A new working document</option></select>')}<div class="quiet-note">${icon('info')}This creates a simulated job with example results. Selected file contents are not read or sent anywhere.</div>`; footer = `${btn('close-modal', 'Cancel', '', '')}${btn('create-import', 'Create demo job', 'plus', 'primary')}`; }
  else if (s.modal === 'add-term') { title = 'Add vocabulary term'; body = `<p class="modal-description">A confirmed term becomes available to future recognition and correction requests.</p>${field('Exact spelling', '<input id="term-name" placeholder="e.g. AudioWorklet" maxlength="80"/>')}${field('Meaning or context', '<input id="term-meaning" placeholder="A brief description, if useful" maxlength="180"/>')}<p class="micro-copy">Scope: this dictation · origin: you confirmed</p>`; footer = `${btn('close-modal', 'Cancel', '', '')}${btn('save-term', 'Add to vocabulary', 'check', 'primary')}`; }
  else if (s.modal === 'add-tag') { title = 'Add a tag'; body = field('Tag name', '<input id="tag-name" placeholder="e.g. Product research" maxlength="40"/>'); footer = `${btn('close-modal', 'Cancel', '', '')}${btn('save-tag', 'Add tag', 'plus', 'primary')}`; }
  else if (s.modal === 'rerun') { const r = s.requests.find(q => q.id === s.requestId); title = 'Create recognition attempt'; body = `<p class="modal-description">Create a new recognition request. The existing result stays in the evidence history.</p>${detail('Audio window', `${time(r.input[0])} – ${time(r.input[1])}`)}${field('Model', `<select id="rerun-model">${MODEL_OPTIONS.filter(m => m !== 'gpt-live-transcribe').map(m => `<option ${m === r.model ? 'selected' : ''}>${m}</option>`).join('')}</select>`)}${field('Context', '<select id="rerun-context"><option value="original">Original frozen context</option><option value="current">Current primer</option></select>')}<div class="quiet-note">${icon('info')}The new result is simulated from fixture data.</div>`; footer = `${btn('close-modal', 'Cancel', '', '')}${btn('confirm-rerun', 'Simulate request', 'loop', 'primary')}`; }
  else { title = 'Keyboard shortcuts'; body = `<div class="shortcut-list">${[['Space', 'Play or pause the audio preview'], ['R', 'Start or stop recording preview'], ['M', 'Add a timeline marker'], ['J / L', 'Back / forward five seconds'], ['⌘ / Ctrl + F', 'Find in this document'], ['⌘ / Ctrl + Z', 'Undo a document edit'], ['Escape', 'Close the open panel or dialog']].map(([k, v]) => `<div><span>${v}</span><kbd>${k}</kbd></div>`).join('')}</div><p class="micro-copy">Single-key shortcuts stay inactive while you’re typing.</p>`; footer = btn('close-modal', 'Got it', '', 'primary'); }
  return `<div class="modal-backdrop" data-action="backdrop"><section class="modal ${wide ? 'wide' : ''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${title}</h2>${ib('close-modal', 'Close dialog', 'close')}</header><div class="modal-body ${wide ? 'settings-body' : ''}">${body}</div><footer class="modal-footer">${footer}</footer></section></div>`;
}

export function renderApp(s) { return `<div class="app-shell ${!s.inspectorOpen ? 'without-inspector' : ''} ${s.focusMode ? 'focus-mode' : ''} ${s.page === 'jobs' ? 'activity-shell' : ''}">${header(s)}${s.page === 'jobs' ? '' : sidebar(s)}${s.page === 'jobs' ? activityView(s) : documentView(s)}${s.page === 'jobs' ? '' : inspector(s) + transport(s)}</div>`; }
